                    </GamifiedButton>
                  )}
                </GamifiedCard>
              )
            })}
          </div>
        )}
      </div>

      {/* 4. Standalone Challenges & Practice Attempts */}
      <div className="flex flex-col gap-4 pt-4 border-t border-slate-200/60">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
