async function recordChallengeSubmission(
  userId: string,
  challengeId: string,
  passed: boolean,
  score: number = 100
): Promise<void> {
  try {
    const now = new Date().toISOString()

    const { data: existingProgress } = await supabase
      .from('challenge_progress')
      .select('attempts_count, best_score, is_completed')
      .eq('user_id', userId)
      .eq('challenge_id', challengeId)
      .maybeSingle()

    const newAttemptsCount = (existingProgress?.attempts_count ?? 0) + 1
    const newBestScore = Math.max(existingProgress?.best_score ?? 0, passed ? score : 0)
    const isCompleted = (existingProgress?.is_completed ?? false) || passed

    await supabase.from('challenge_attempts').insert({
      user_id: userId,
      challenge_id: challengeId,
      attempt_number: newAttemptsCount,
      status: passed ? 'passed' : 'failed',
      score: passed ? score : 0,
      passed,
      completed_at: now,
    })

    if (existingProgress) {
      await supabase
        .from('challenge_progress')
        .update({
          is_completed: isCompleted,
          best_score: newBestScore,
          attempts_count: newAttemptsCount,
          last_attempt_at: now,
          completed_at: isCompleted ? now : null,
        })
        .eq('user_id', userId)
        .eq('challenge_id', challengeId)
    } else {
      await supabase
        .from('challenge_progress')
        .insert({
          user_id: userId,
          challenge_id: challengeId,
          is_completed: isCompleted,
          best_score: newBestScore,
          attempts_count: newAttemptsCount,
          last_attempt_at: now,
          completed_at: isCompleted ? now : null,
        })
    }
  } catch (err) {
    console.error('Error recording challenge submission:', err)
  }
}

