          localStorage.setItem(`onboarded_${user.id}`, 'true')
          setHasCompletedOnboarding(true)
        }} />
      </div>
    )
  }

  // 4. Global App Shell Framework
  return (
    <>
      {bladeCursorActive && <BladeOfChaosCursor />}
      {isAdmin ? <AdminShell /> : <AppShell />}
    </>
  )
}

