export const BloodArenaBattleView: React.FC<BloodArenaBattleViewProps> = ({ battleId, userId, onExit }) => {
  const { access, battle, exercises, teamMembers, teamProgress, loading, refreshLobby } = useBattleLobby(battleId, userId)
