            title="Toggle Scroll of Labor"
          >
            {leftCollapsed ? <Maximize2 className="w-3.5 h-3.5" /> : <Minimize2 className="w-3.5 h-3.5" />}
          </button>
          <button
            type="button"
            onClick={() => setRightCollapsed(!rightCollapsed)}
