            {rightCollapsed ? <Maximize2 className="w-3.5 h-3.5" /> : <Minimize2 className="w-3.5 h-3.5" />}
          </button>
        </div>
      </div>

      {/* ── Tri-Pane Layout ─────────────────────────────────────── */}
      <div className="flex flex-1 overflow-hidden">

        {/* Pane 1: Scroll of Labor (28%) */}
        {!leftCollapsed && (
          <div className="flex flex-col shrink-0 overflow-hidden"
