              >
                LEVEL {stats.level} {theme === 'classic' ? 'ADVENTURER' : 'WARRIOR'}
              </span>
            </div>

            <h1
              className="font-bold uppercase tracking-wide leading-tight text-3xl sm:text-4xl text-transparent bg-clip-text"
              style={{
                backgroundImage: theme === 'classic'
                  ? 'none'
                  : 'linear-gradient(135deg, #FFFFFF 0%, #F5E6E6 40%, #D4A373 80%, #C59B27 100%)',
                color: theme === 'classic' ? 'var(--theme-text-primary, #0F172A)' : undefined,
                fontFamily: "var(--theme-font-heading, 'Cinzel', serif)",
                filter: theme === 'classic' ? 'none' : 'drop-shadow(0 2px 8px rgba(0,0,0,0.8))',
              }}
            >
              {theme === 'classic' ? `Good day, ${username} ✨` : `Hail, ${username}`}
