    setIsRunningQuickCode(true)
    setActiveBottomTab('terminal')

    try {
      const exec = await executeCode('javascript', code, '')
      setTerminalOutput({
        stdout: exec.stdout || '',
        stderr: exec.stderr || '',
        status: exec.status,
      })
    } catch (err: any) {
      setTerminalOutput({
        stdout: '',
        stderr: err?.message || 'Execution error.',
        status: 'error',
      })
    } finally {
      setIsRunningQuickCode(false)
    }
  }

