            return (
              <div
                key={project.id}
                className="bg-[#120808] rounded-2xl border border-[#3D1C1C] hover:border-[#8C2828] p-5 shadow-lg hover:shadow-[0_0_20px_rgba(140,40,40,0.4)] transition-all flex flex-col justify-between group"
