            <div className="flex flex-col">
              <span
                className="font-extrabold tracking-[0.22em] text-base leading-tight"
                style={{ fontFamily: 'var(--theme-font-heading, "Cinzel", serif)', color: 'var(--theme-text-primary, #F5E8E8)' }}
