            title={`${streak}-Day Streak`}
            style={{
              background: 'var(--theme-hud-streak-bg, rgba(220,38,38,0.15))',
              borderColor: 'var(--theme-hud-streak-border, #DC2626)',
              color: 'var(--theme-hud-streak-text, #FF3D00)',
