              )}
              initial={animate ? { scaleX: 0, opacity: 0 } : false}
              animate={{ scaleX: 1, opacity: 1 }}
              transition={{ delay: i * 0.05, duration: 0.3, ease: "easeOut" }}
              style={{ transformOrigin: "left" }}
            />
          )
        })}
