async function fetchUserBadges(userId?: string): Promise<BadgeItem[]> {
  try {
    const { data: allBadges, error: badgesErr } = await supabase
      .from('badges')
      .select('*')
      .order('created_at', { ascending: true })

    if (badgesErr || !allBadges || allBadges.length === 0) {
      return []
    }

    const unlockedMap = new Map<string, string>()

    if (userId) {
      const { data: userBadges } = await supabase
        .from('user_badges')
        .select('badge_id, unlocked_at')
        .eq('user_id', userId)

      if (userBadges) {
        userBadges.forEach((ub) => {
          unlockedMap.set(ub.badge_id, ub.unlocked_at)
        })
      }
    }

    return allBadges.map((b) => ({
      id: b.id,
      slug: b.slug,
      title: b.title,
      description: b.description || '',
      icon: b.icon || '🏅',
      category: b.category || 'general',
      isUnlocked: unlockedMap.has(b.id),
      unlockedAt: unlockedMap.get(b.id),
    }))
  } catch (err) {
    console.error('Error fetching badges:', err)
    return []
  }
}

