useAchievementsAndNotifications(userId?: string) {
  const [badges, setBadges] = useState<BadgeItem[]>([])
  const [achievements, setAchievements] = useState<AchievementItem[]>([])
  const [activities, setActivities] = useState<ActivityItem[]>([])
  const [notifications, setNotifications] = useState<NotificationItem[]>([])
  const [loading, setLoading] = useState(true)

  const loadData = useCallback(async () => {
    if (!userId) {
      setBadges([])
      setAchievements([])
      setActivities([])
      setNotifications([])
      setLoading(false)
      return
    }

    setLoading(true)
    try {
      await syncUserBadgesAndAchievements(userId)

      const [loadedBadges, loadedAchievements, notifRes, actRes] = await Promise.all([
        fetchUserBadges(userId),
        fetchUserAchievements(userId),
        supabase
          .from('notifications')
          .select('*')
          .eq('user_id', userId)
          .order('created_at', { ascending: false })
          .limit(10),
        supabase
          .from('activity_history')
          .select('*')
          .eq('user_id', userId)
          .order('created_at', { ascending: false })
          .limit(10),
      ])

      setBadges(loadedBadges)
      setAchievements(loadedAchievements)

      if (notifRes.data) {
        setNotifications(
          notifRes.data.map((n) => ({
            id: n.id,
            title: n.title,
            message: n.message,
            icon: n.icon || '🔔',
            isRead: n.is_read,
            createdAt: formatRelativeOrLocaleTime(n.created_at),
          }))
        )
      } else {
        setNotifications([])
      }

      if (actRes.data) {
        setActivities(
          actRes.data.map((a) => ({
            id: a.id,
            actionType: a.action_type,
            title: a.title,
            createdAt: formatRelativeOrLocaleTime(a.created_at),
          }))
        )
      } else {
        setActivities([])
      }
    } catch (err) {
      console.error('Error loading achievements and notifications:', err)
    } finally {
      setLoading(false)
    }
  }, [userId])

  useEffect(() => {
    let mounted = true
    if (userId && mounted) {
      loadData()
    } else if (!userId) {
      setLoading(false)
    }
    return () => {
      mounted = false
    }
  }, [userId, loadData])

  const markRead = useCallback(async (id: string) => {
    setNotifications((prev) => prev.map((n) => (n.id === id ? { ...n, isRead: true } : n)))
    await markNotificationAsRead(id)
  }, [])

  const logAction = useCallback(async (actionType: string, title: string) => {
    if (!userId) return
    await recordUserActivity(userId, actionType, title)
    await loadData()
  }, [userId, loadData])

  const unreadCount = notifications.filter((n) => !n.isRead).length

  return {
    badges,
    achievements,
    activities,
    notifications,
    unreadCount,
    loading,
    markRead,
    logAction,
    refreshAll: loadData,
  }
}

