function useFestLobby(festId: string | null, userId?: string) {
  const [access, setAccess] = useState<FestParticipationAccess | null>(null)
  const [challenges, setChallenges] = useState<FestChallenge[]>([])
  const [activeChallenge, setActiveChallenge] = useState<FestChallenge | null>(null)
  const [loading, setLoading] = useState(true)

  const loadLobby = useCallback(async () => {
    if (!festId || !userId) {
      setAccess(null)
      setChallenges([])
      setActiveChallenge(null)
      setLoading(false)
      return
    }

    setLoading(true)
    const accessRes = await checkFestParticipationAccess(festId, userId)
    setAccess(accessRes)

    if (accessRes.allowed) {
      const chs = await fetchFestChallenges(festId)
      setChallenges(chs)
      if (chs.length > 0) {
        setActiveChallenge((prev) => prev || chs[0])
      }
    } else {
      setChallenges([])
      setActiveChallenge(null)
    }

    setLoading(false)
  }, [festId, userId])

  useEffect(() => {
    loadLobby()
  }, [loadLobby])

  // Realtime updates for challenges and fest state
  useEffect(() => {
    if (!festId) return

    const channel = supabase
      .channel(`fest_lobby_${festId}`)
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'arcade_fest_challenges',
          filter: `fest_id=eq.${festId}`,
        },
        () => {
          loadLobby()
        }
      )
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'arcade_fests',
          filter: `id=eq.${festId}`,
        },
        () => {
          loadLobby()
        }
      )
      .subscribe()

    return () => {
      supabase.removeChannel(channel)
    }
  }, [festId, loadLobby])

  return {
    access,
    challenges,
    activeChallenge,
    setActiveChallenge,
    loading,
    refreshLobby: loadLobby,
  }
}

