function useFestLeaderboard(festId: string | null) {
  const [leaderboard, setLeaderboard] = useState<FestLeaderboardEntry[]>([])
  const [loading, setLoading] = useState(true)

  const loadLeaderboard = useCallback(async () => {
    if (!festId) {
      setLeaderboard([])
      setLoading(false)
      return
    }

    const data = await fetchFestLeaderboard(festId)
    setLeaderboard(data)
    setLoading(false)
  }, [festId])

  useEffect(() => {
    loadLeaderboard()
  }, [loadLeaderboard])

  // Realtime subscription for score events and registration changes
  useEffect(() => {
    if (!festId) return

    const channel = supabase
      .channel(`fest_leaderboard_${festId}`)
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'arcade_fest_scores',
          filter: `fest_id=eq.${festId}`,
        },
        () => {
          loadLeaderboard()
        }
      )
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'arcade_fest_registrations',
          filter: `fest_id=eq.${festId}`,
        },
        () => {
          loadLeaderboard()
        }
      )
      .subscribe()

    return () => {
      supabase.removeChannel(channel)
    }
  }, [festId, loadLeaderboard])

  return {
    leaderboard,
    loading,
    refreshLeaderboard: loadLeaderboard,
  }
}

