async function toggleBlogLike(userId: string, blogId: string): Promise<{ liked: boolean; newCount: number }> {
  try {
    await ensureProfileExists(userId)

    const { data: existingLike } = await supabase
      .from('blog_likes')
      .select('blog_id')
      .eq('user_id', userId)
      .eq('blog_id', blogId)
      .maybeSingle()

    if (existingLike) {
      await supabase
        .from('blog_likes')
        .delete()
        .eq('user_id', userId)
        .eq('blog_id', blogId)
    } else {
      await supabase
        .from('blog_likes')
        .insert({ user_id: userId, blog_id: blogId })
    }

    const { count } = await supabase
      .from('blog_likes')
      .select('*', { count: 'exact', head: true })
      .eq('blog_id', blogId)

    const newCount = count ?? 0

    // Update blog likes_count column for synchronization
    await supabase.from('blogs').update({ likes_count: newCount }).eq('id', blogId)

    if (!existingLike) {
      await recordUserActivity(userId, 'blog_liked', `Liked a community blog article 📖`)
    }

    return {
      liked: !existingLike,
      newCount,
    }
  } catch (err) {
    console.error('Error toggling blog like:', err)
    return { liked: false, newCount: 0 }
  }
}

