  followerId: string,
  followingId: string,
  followerName?: string
): Promise<boolean> {
  if (followerId === followingId) return false
  try {
    const { data: existing } = await supabase
      .from('user_follows')
      .select('follower_id')
      .eq('follower_id', followerId)
      .eq('following_id', followingId)
