async function updateStreakAndDailyActivity(userId: string): Promise<number> {
  try {
    const { data: profile } = await supabase
      .from('profiles')
      .select('streak, last_active_date')
      .eq('id', userId)
      .maybeSingle()

    if (!profile) return 0

    const todayStr = new Date().toISOString().split('T')[0]
    const lastActiveStr = profile.last_active_date ? new Date(profile.last_active_date).toISOString().split('T')[0] : null

    let newStreak = profile.streak || 0

    if (!lastActiveStr) {
      newStreak = 1
    } else if (lastActiveStr === todayStr) {
      newStreak = Math.max(1, newStreak)
    } else {
      const todayDate = new Date(todayStr).getTime()
      const lastDate = new Date(lastActiveStr).getTime()
      const diffDays = Math.round((todayDate - lastDate) / (1000 * 60 * 60 * 24))

      if (diffDays === 1) {
        newStreak += 1
      } else {
        newStreak = 1
      }
    }

    await supabase
      .from('profiles')
      .update({
        streak: newStreak,
        last_active_date: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      })
      .eq('id', userId)

    return newStreak
  } catch (err) {
    console.error('Error updating streak:', err)
    return 0
  }
}

