async function startProject(userId: string, projectId: string, firstStepId?: string): Promise<boolean> {
  try {
    const now = new Date().toISOString()
    const { data: existing } = await supabase
      .from('project_enrollments')
      .select('id, status, is_completed')
      .eq('user_id', userId)
      .eq('project_id', projectId)
      .maybeSingle()

    // Prevent completed project from reverting
    if (existing) {
      await supabase
        .from('project_enrollments')
        .update({ last_accessed_at: now })
        .eq('id', existing.id)
      return true
    }

    const { error } = await supabase.from('project_enrollments').insert({
      user_id: userId,
      project_id: projectId,
      status: 'in_progress',
      is_completed: false,
