function getTimeGreeting(): TimeGreeting {
  const hour = new Date().getHours()
  if (hour >= 5 && hour < 12) {
    return {
      greeting: 'Good morning',
      emoji: '👋',
      period: 'morning',
    }
  } else if (hour >= 12 && hour < 17) {
    return {
      greeting: 'Good afternoon',
      emoji: '☀️',
      period: 'afternoon',
    }
  } else if (hour >= 17 && hour < 22) {
    return {
      greeting: 'Good evening',
      emoji: '✨',
      period: 'evening',
    }
  } else {
    return {
      greeting: 'Good evening',
      emoji: '🌙',
      period: 'night',
    }
  }
}

