function truncate(str?: string): string {
  if (!str) return ''
  if (str.length > MAX_OUTPUT_CHARS) {
    return str.slice(0, MAX_OUTPUT_CHARS) + '\n\n[... Output truncated: Exceeded maximum allowed size ...]'
  }
  return str
}
